export const facts: Fact[] = rows
  .trim()
  .split('\n')
  .map((line) => {
    const [id, pages, chapter, category, label, prompt, answer, aliases, difficulty, details] =
      line.split('|');
    return {
      id,
      sourcePages: pages.split(',').map(Number),
      chapter: Number(chapter),
      category: category as Category,
      label,
      prompt,
      answer,
      aliases: aliases ? aliases.split('~') : [],
      difficulty: Number(difficulty) as Difficulty,
      details,
    };
  });
export const factById = Object.fromEntries(facts.map((f) => [f.id, f])) as Record<string, Fact>;
